  ACTS['edit-customer'] = t => { const c = cust(t.dataset.id); formDialog({ title: `Edit customer ${c.name}`, kind: 'drawer', submit: 'Save', cancel: 'Close', name: 'save-customer', fields: [{ name: 'name', label: 'Company name', required: true, value: c.name, cls: 'span2' }, { name: 'mc', label: 'MC number', value: c.mc }, { name: 'email', label: 'Billing email', type: 'email', value: c.email }, { name: 'address', label: 'Address', value: c.address, cls: 'span2' }, { name: 'billingType', label: 'Customer billing type', type: 'select', options: ['FACTORING COMPANY', 'DIRECT BILL', 'QUICK PAY'], value: c.billingType, placeholder: false }, { name: 'terms', label: 'Payment terms', type: 'select', options: ['Net 30', 'Net 15', 'Net 45', 'Quick pay 2%'], value: c.terms, placeholder: false }, { name: 'creditLimit', label: 'Credit limit', type: 'money', value: c.creditLimit }, { name: 'contact', label: 'Contact person', value: c.contact }], build: p => ({ id: c.id, ...p }), apply: p => Object.assign(c, { ...p, creditLimit: +p.creditLimit || 0 }) }); };
